'use strict';

function finite(value) {
  return typeof value === 'number' && Number.isFinite(value);
}

function plainObject(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function validateBody(body) {
  if (!plainObject(body) ||
      !finite(body.x) || !finite(body.y) ||
      !finite(body.width) || body.width <= 0 ||
      !finite(body.height) || body.height <= 0 ||
      !finite(body.mass) || body.mass <= 0 ||
      !finite(body.vx) || !finite(body.vy) || !finite(body.angle) ||
      !finite(body.restitution) || body.restitution < 0 || body.restitution > 1) {
    throw new TypeError('Invalid body');
  }
}

function createBody(options) {
  if (!plainObject(options)) {
    throw new TypeError('Options must be a plain object');
  }
  const body = {
    x: options.x,
    y: options.y,
    width: options.width,
    height: options.height,
    mass: options.mass,
    vx: options.vx === undefined ? 0 : options.vx,
    vy: options.vy === undefined ? 0 : options.vy,
    angle: options.angle === undefined ? 0 : options.angle,
    restitution: options.restitution || 0.25
  };
  validateBody(body);
  return Object.freeze(body);
}

function advanceBody(body, force, dt) {
  validateBody(body);
  if (!plainObject(force) || !finite(force.x) || !finite(force.y) ||
      !finite(dt) || dt < 0) {
    throw new TypeError('Invalid integration arguments');
  }
  const vx = body.vx + (force.x / body.mass) * dt;
  const vy = body.vy + (force.y / body.mass) * dt;
  return Object.freeze({
    ...body,
    x: body.x + vx * dt,
    y: body.y + vy * dt,
    vx,
    vy
  });
}

function getCorners(body) {
  validateBody(body);
  const centerX = body.x + body.width / 2;
  const centerY = body.y + body.height / 2;
  const cos = Math.cos(body.angle);
  const sin = Math.sin(body.angle);
  const offsets = [
    [-body.width / 2, -body.height / 2],
    [body.width / 2, -body.height / 2],
    [body.width / 2, body.height / 2],
    [-body.width / 2, body.height / 2]
  ];
  return offsets.map(([dx, dy]) => ({
    x: centerX + dx * cos - dy * sin,
    y: centerY + dx * sin + dy * cos
  }));
}

module.exports = { createBody, advanceBody, getCorners };

