'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api).sort(), ['advanceBody', 'createBody', 'getCorners']);
const { createBody, advanceBody, getCorners } = api;

const body = createBody({ x: 1, y: 2, width: 4, height: 2, mass: 2 });
assert.deepEqual(body, { x: 1, y: 2, width: 4, height: 2, mass: 2, vx: 0, vy: 0, angle: 0, restitution: 0.25 });
assert.equal(Object.isFrozen(body), true);
const zeroRestitution = createBody({ x: 0, y: 0, width: 1, height: 1, mass: 1, vx: -2, vy: 3, angle: 0.5, restitution: 0 });
assert.equal(zeroRestitution.restitution, 0);

for (const options of [null, [], {}, { x: 0, y: 0, width: 0, height: 1, mass: 1 }, { x: 0, y: 0, width: 1, height: -1, mass: 1 }, { x: 0, y: 0, width: 1, height: 1, mass: 0 }, { x: Infinity, y: 0, width: 1, height: 1, mass: 1 }, { x: 0, y: 0, width: 1, height: 1, mass: 1, vx: NaN }, { x: 0, y: 0, width: 1, height: 1, mass: 1, restitution: -0.1 }, { x: 0, y: 0, width: 1, height: 1, mass: 1, restitution: 1.1 }]) {
  assert.throws(() => createBody(options), TypeError);
}

const moving = createBody({ x: 1, y: 2, width: 4, height: 2, mass: 2, vx: 3, vy: -1, angle: 0.4, restitution: 1 });
const force = { x: 4, y: 6 };
const advanced = advanceBody(moving, force, 0.5);
assert.deepEqual(advanced, { x: 3, y: 2.25, width: 4, height: 2, mass: 2, vx: 4, vy: 0.5, angle: 0.4, restitution: 1 });
assert.equal(Object.isFrozen(advanced), true);
assert.notStrictEqual(advanced, moving);
assert.deepEqual(moving, { x: 1, y: 2, width: 4, height: 2, mass: 2, vx: 3, vy: -1, angle: 0.4, restitution: 1 });
assert.deepEqual(force, { x: 4, y: 6 });
const dtZero = advanceBody(moving, { x: 100, y: 100 }, 0);
assert.notStrictEqual(dtZero, moving);
assert.deepEqual(dtZero, moving);
for (const args of [[{}, force, 1], [moving, null, 1], [moving, { x: 1 }, 1], [moving, { x: NaN, y: 0 }, 1], [moving, force, -1], [moving, force, Infinity]]) {
  assert.throws(() => advanceBody(...args), TypeError);
}

const axisBody = createBody({ x: 10, y: 20, width: 4, height: 2, mass: 1 });
const corners = getCorners(axisBody);
assert.deepEqual(corners, [{ x: 10, y: 20 }, { x: 14, y: 20 }, { x: 14, y: 22 }, { x: 10, y: 22 }]);
const cornersAgain = getCorners(axisBody);
assert.notStrictEqual(cornersAgain, corners);
for (let i = 0; i < 4; i++) assert.notStrictEqual(cornersAgain[i], corners[i]);
corners[0].x = 999;
assert.equal(cornersAgain[0].x, 10);

const rotated = getCorners(createBody({ x: 0, y: 0, width: 2, height: 2, mass: 1, angle: Math.PI / 2 }));
const expected = [{ x: 2, y: 0 }, { x: 2, y: 2 }, { x: 0, y: 2 }, { x: 0, y: 0 }];
rotated.forEach((point, i) => {
  assert.ok(Math.abs(point.x - expected[i].x) < 1e-12);
  assert.ok(Math.abs(point.y - expected[i].y) < 1e-12);
});
assert.throws(() => getCorners(), TypeError);
assert.throws(() => getCorners({}), TypeError);

